11	#ifndef EMITASC_OPS_TD
12	#define EMITASC_OPS_TD
13	
14	include "Dialect.td"
15	include "Types.td"
16	
17	include "mlir/Interfaces/CastInterfaces.td"
18	include "mlir/Interfaces/SideEffectInterfaces.td"
19	include "mlir/Interfaces/ViewLikeInterface.td"
20	include "mlir/IR/BuiltinAttributeInterfaces.td"
21	
22	class EmitAsc_Op<string mnemonic, list<Trait> traits = []>
23	    : Op<EmitAsc_Dialect, mnemonic, traits> {
24	  let cppNamespace = "::mlir::emitasc";
25	}
26	
27	def EmitAsc_CallOpaqueOp : EmitAsc_Op<"call_opaque"> {
28	  let summary = "Call C++ function by its name";
29	  let description = [{
30	    Callee name must be demangled. It may include namespaces and template
31	    arguments. Constructor should be represented as its parent class name.
32	  }];
33	  let arguments = (ins StrAttr:$callee, Variadic<AnyType>:$callee_operands);
34	  let results = (outs Optional<AnyType>:$result);
35	  let assemblyFormat = [{
36	    $callee `(` $callee_operands `)` attr-dict `:`
37	    functional-type($callee_operands, $result)
38	  }];
39	}
40	
41	def EmitAsc_CopyStructOp : EmitAsc_Op<"copy_struct"> {
42	  let summary = "Create local structure and perform memcpy from another one";
43	  let arguments = (ins AnyMemRef:$base);
44	  let results = (outs AnyType:$result);
45	  let assemblyFormat = "$base attr-dict `:` type($base) `,` type($result)";
46	}
47	
48	def EmitAsc_DeclarePyStructOp : EmitAsc_Op<"declare_py_struct", [Pure]> {
49	  let summary = "Declare custom structure";
50	  let arguments = (ins TypeAttr:$pystruct);
51	  let assemblyFormat = "$pystruct attr-dict";
52	}
53	
54	def EmitAsc_DereferenceOp : EmitAsc_Op<"dereference", [Pure]> {
55	  let summary = "Dereference pointer to underlying object (unary `operator*`)";
56	  let arguments = (ins AnyMemRef:$base);
57	  let results = (outs AnyType:$result);
58	  let assemblyFormat = "$base attr-dict `:` type($base) `,` type($result)";
59	}
60	
61	def EmitAsc_MemberOp : EmitAsc_Op<"member"> {
62	  let arguments = (ins AnyType:$base, StrAttr:$field);
63	  let results = (outs AnyType:$result);
64	  let assemblyFormat = [{
65	    $base $field attr-dict `:` type($base) `,` type($result)
66	  }];
67	}
68	
69	def EmitAsc_MemberPtrOp : EmitAsc_Op<"member_ptr", [Pure]> {
70	  let summary = "Access pointer-to-struct member (`operator->`)";
71	  let description = [{
72	    This operation represents getting an address of a struct member at the given
73	    pointer, and it should be emitted as the following:
74	
75	    ```cpp
76	    auto *result = (ResultT *)&base->member;
77	    ```
78	  }];
79	  let arguments = (ins AnyMemRef:$base, IndexAttr:$index, OptionalAttr<StrAttr>:$field);
80	  let results = (outs AnyMemRef:$result);
81	  let assemblyFormat = [{
82	    $base `[` $index `]` ($field^)? attr-dict `:` type($base) `,` type($result)
83	  }];
84	}
85	
86	def EmitAsc_MemberRefOp : EmitAsc_Op<"member_ref", [Pure]> {
87	  let summary = "Access pointer-to-struct member (emit result as reference)";
88	  let description = [{
89	    This operation represents obtaining a struct member at the given pointer as
90	    a reference, and it should be emitted as the following:
91	
92	    ```cpp
93	    ResultT &result = base->member;
94	    ```
95	  }];
96	  let arguments = (ins AnyMemRef:$base, IndexAttr:$index, OptionalAttr<StrAttr>:$field);
97	  let results = (outs AnyType:$result);
98	  let assemblyFormat = [{
99	    $base `[` $index `]` ($field^)? attr-dict `:` type($base) `,` type($result)
100	  }];
101	}
102	
103	def EmitAsc_SetMemberOp : EmitAsc_Op<"set_member"> {
104	  let arguments = (ins AnyType:$base, StrAttr:$field, AnyType:$value);
105	  let assemblyFormat = [{
106	    $base $field `,` $value attr-dict `:` type($base) `,` type($value)
107	  }];
108	}
109	
110	def EmitAsc_PtrOffsetOp : EmitAsc_Op<"ptr_offset", [
111	  Pure, DeclareOpInterfaceMethods<ViewLikeOpInterface>
112	]> {
113	  let summary = "Apply `operator+` between pointer and offset";
114	  let arguments = (ins AnyMemRef:$base, OptionalAttr<IndexAttr>:$staticOffset,
115	                       Optional<Index>:$dynamicOffset);
116	  let results = (outs AnyMemRef:$result);
117	  let assemblyFormat = [{
118	    $base `[` ($dynamicOffset^):($staticOffset ` `)? `]` attr-dict `:`
119	    type($base) `,` type($result)
120	  }];
121	  let hasFolder = 1;
122	}
123	
124	def EmitAsc_ReinterpretCastOp : EmitAsc_Op<"reinterpret_cast", [
125	  Pure, DeclareOpInterfaceMethods<CastOpInterface>
126	]> {
127	  let summary = "Convert between types by reinterpreting the underlying data";
128	  let arguments = (ins AnyType:$source);
129	  let results = (outs AnyType:$result);
130	  let assemblyFormat = "$source attr-dict `:` type($source) `to` type($result)";
131	}
132	
133	def EmitAsc_VariableOp : EmitAsc_Op<"variable", [Pure]> {
134	  let summary = "Define a mutable variable";
135	  let description = [{
136	    This operation combines an allocation and storing a value to `memref<1x...>`.
137	    Its element type must be the same as _init_ type (either static or dynamic).
138	  }];
139	  let arguments = (ins OptionalAttr<TypedAttrInterface>:$staticInit,
140	                       Optional<AnyType>:$dynamicInit);
141	  let results = (outs AnyNon0RankedMemRef:$result);
142	  let assemblyFormat = [{
143	    attr-dict ($dynamicInit^ `:` type($dynamicInit)):($staticInit)? `,` type($result)
144	  }];
145	  let builders = [
146	    OpBuilder<(ins "OpFoldResult":$init), [{
147	      TypedAttr staticInit;
148	      Value dynamicInit;
149	      Type type;
150	      if (auto di = dyn_cast<Value>(init)) {
151	        dynamicInit = di;
152	        type = di.getType();
153	      } else {
154	        auto si = cast<TypedAttr>(cast<Attribute>(init));
155	        staticInit = si;
156	        type = si.getType();
157	      }
158	      build($_builder, $_state, MemRefType::get(1, type), staticInit, dynamicInit);
159	    }]>,
160	  ];
161	  let extraClassDeclaration = [{
162	    bool isStatic();
163	    OpFoldResult getInit(bool fold = true);
164	  }];
165	}
166	
167	def EmitAsc_VerbatimOp : EmitAsc_Op<"verbatim"> {
168	  let arguments = (ins StrAttr:$value, Variadic<AnyType>:$args);
169	  let assemblyFormat = "$value ($args^ `:` type($args))?  attr-dict";
170	}
171	
172	#endif // EMITASC_OPS_TD
